	@Test
	void connectionCloseCleansAbandonedIterationsBeforeCleanerLaneRuns() throws InterruptedException {
		AbstractSailConnection connection = newConnection();
		CountingIteration delegate = new CountingIteration();
		ReferenceQueue<CloseableIteration<Integer>> collected = new ReferenceQueue<>();
		try (BlockedCleanerLane cleanerLane = new BlockedCleanerLane()) {
			WeakReference<CloseableIteration<Integer>> reference = registerAbandoned(connection, delegate, collected);
			System.gc();
			assertThat(collected.remove(TimeUnit.SECONDS.toMillis(10)))
					.as("the registered outer iteration was collected")
					.isSameAs(reference);
			assertThat(delegate.closes.get()).as("the cleaner lane cannot yet close the delegate").isZero();

			assertThatCode(connection::close).doesNotThrowAnyException();

			assertThat(delegate.closes.get()).as("owner close completes abandoned cleanup exactly once").isOne();
			assertThat(connection.hasActiveIterations()).isFalse();
			assertThat(cleanerLane.release.getCount()).as("cleanup completed while the cleaner remains blocked")
					.isOne();
		} finally {
			connection.close();
		}
	}

	@Test
	void untrackedResultStopsAtItsNextPullOnceItsCreatingWorkloadIsCancelled() {
		AbstractSailConnection connection = newConnection(false);
		CancellationSignal creator = new CancellationSignal();
		CountingIteration delegate = new CountingIteration();
		CancellationSignal previous = CancellationSignal.swapCurrent(creator);
		CloseableIteration<Integer> iteration;
		try {
			iteration = connection.registerIteration(delegate);
		} finally {
			CancellationSignal.restoreCurrent(previous);
		}
		try {
			creator.cancel();
			assertThatThrownBy(iteration::hasNext).isInstanceOf(SailException.class)
					.hasMessage("The workload that created this result is shutting down");
			assertThat(CancellationSignal.current()).as("a rejected pull restores the caller's signal")
					.isSameAs(CancellationSignal.NONE);
		} finally {
			iteration.close();
			connection.close();
		}
		assertThat(delegate.closes.get()).as("cleanup after cancellation still closes the delegate once").isOne();
	}

	@Test
	void closeInterruptsAndDrainsAnInFlightResultPullBeforeTeardown() throws Exception {
		AbstractSailConnection connection = newConnection(true);
		AtomicBoolean teardownStarted = new AtomicBoolean();
		AtomicBoolean teardownStartedBeforePullReturned = new AtomicBoolean();
		doAnswer(invocation -> {
			teardownStarted.set(true);
			return null;
		}).when(connection).closeInternal();
		CountDownLatch pullEntered = new CountDownLatch(1);
		CountDownLatch pullInterrupted = new CountDownLatch(1);
		CountDownLatch releasePull = new CountDownLatch(1);
		CountingIteration delegate = new CountingIteration() {
			@Override
			public boolean hasNext() {
				pullEntered.countDown();
				boolean interrupted = false;
				while (releasePull.getCount() != 0) {
					try {
						releasePull.await();
					} catch (InterruptedException cancellation) {
						interrupted = true;
						pullInterrupted.countDown();
					}
				}
				teardownStartedBeforePullReturned.set(teardownStarted.get());
				if (interrupted) {
					Thread.currentThread().interrupt();
				}
				return false;
			}
		};
		CloseableIteration<Integer> iteration = connection.registerIteration(delegate);
		AtomicReference<Throwable> pullFailure = new AtomicReference<>();
		AtomicReference<Throwable> closeFailure = new AtomicReference<>();
		Thread puller = new Thread(() -> {
			try {
				iteration.hasNext();
			} catch (Throwable failure) {
				pullFailure.set(failure);
			}
		}, "in-flight-result-pull");
		Thread closer = new Thread(() -> {
			try {
				connection.close();
			} catch (Throwable failure) {
				closeFailure.set(failure);
			}
		}, "connection-close-during-pull");
		puller.start();
		try {
			assertTrue(pullEntered.await(10, TimeUnit.SECONDS), "the result pull must enter its delegate");
			closer.start();
			assertTrue(pullInterrupted.await(10, TimeUnit.SECONDS),
					"close must interrupt the thread inside the result pull");
			assertThat(teardownStarted.get()).as("teardown must wait for the in-flight pull").isFalse();
		} finally {
			releasePull.countDown();
			puller.join(TimeUnit.SECONDS.toMillis(10));
			closer.join(TimeUnit.SECONDS.toMillis(10));
		}
		assertThat(puller.isAlive()).isFalse();
		assertThat(closer.isAlive()).isFalse();
		assertThat(pullFailure.get()).isNull();
		assertThat(closeFailure.get()).isNull();
		assertThat(teardownStartedBeforePullReturned.get()).as("the pull returned before native teardown").isFalse();
		assertThat(teardownStarted.get()).isTrue();
		assertThat(delegate.closes.get()).as("exhaustion closes the delegate exactly once").isOne();
	}

