	@Test
	void explicitCleanupWaitsForAlreadyStartedCleanerClose() throws Exception {
		CountDownLatch closeStarted = new CountDownLatch(1);
		CountDownLatch ownerStarted = new CountDownLatch(1);
		CountDownLatch releaseClose = new CountDownLatch(1);
		AtomicBoolean closeCompleted = new AtomicBoolean();
		CountingIteration delegate = new CountingIteration() {
			@Override
			public void close() {
				if (closes.incrementAndGet() == 1) {
					closeStarted.countDown();
					await(releaseClose);
					closeCompleted.set(true);
				}
			}
		};
		CapturingCleaner cleaner = new CapturingCleaner();
		CleanerIteration<Integer> iteration = new CleanerIteration<>(delegate, cleaner);
		try (ExecutorService executor = Executors.newFixedThreadPool(2)) {
			Future<?> cleaning = executor.submit(cleaner.registration::clean);
			try {
				assertTrue(closeStarted.await(10, TimeUnit.SECONDS), "the cleaner did not start delegate close");
				Future<?> ownerClosing = executor.submit(() -> {
					ownerStarted.countDown();
					iteration.close();
					assertThat(closeCompleted.get()).as("explicit cleanup returns only after delegate close completes")
							.isTrue();
				});
				assertTrue(ownerStarted.await(10, TimeUnit.SECONDS), "the explicit cleanup task did not start");
				releaseClose.countDown();
				cleaning.get(10, TimeUnit.SECONDS);
				ownerClosing.get(10, TimeUnit.SECONDS);
				assertThat(delegate.closes.get()).as("cleaner and owner share one completed close").isOne();
			} finally {
				releaseClose.countDown();
			}
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			assertTrue(latch.await(30, TimeUnit.SECONDS), "delegate close release was not signalled");
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new AssertionError(interrupted);
		}
	}

	private static final class CapturingCleaner extends ConcurrentCleaner {
		Cleaner.Cleanable registration;

		@Override
		public Cleaner.Cleanable register(Object referent, Runnable action) {
			registration = super.register(referent, action);
			return registration;
		}
	}

